48	  private loadPatternsFromFiles(): void {
49	    // Iterate in reverse order so that the first file in the list is processed last.
50	    // This gives the first file the highest priority, as patterns added later override earlier ones.
51	    for (const fileName of [...this.fileNames].reverse()) {
52	      const patterns = this.parseIgnoreFile(fileName);
53	      this.patterns.push(...patterns);
54	      this.ig.add(patterns);
55	    }
56	  }
