79	    if (this.patterns.length === 0) {
80	      return false;
81	    }
82	
83	    const normalizedPath = getNormalizedRelativePath(
84	      this.projectRoot,
85	      filePath,
86	      isDirectory,
87	    );
88	    if (
89	      normalizedPath === null ||
90	      normalizedPath === '' ||
91	      normalizedPath === '/'
