16	export class GitIgnoreParser implements GitIgnoreFilter {
17	  private projectRoot: string;
18	  private cache: Map<string, Ignore> = new Map();
19	  private globalPatterns: Ignore | undefined;
20	  private processedExtraPatterns: Ignore;
21	
22	  constructor(
23	    projectRoot: string,
24	    private readonly extraPatterns?: string[],
25	  ) {
26	    this.projectRoot = path.resolve(projectRoot);
27	    this.processedExtraPatterns = ignore();
28	    if (this.extraPatterns) {
29	      // extraPatterns are assumed to be from project root (like .geminiignore)
30	      this.processedExtraPatterns.add(
31	        this.processPatterns(this.extraPatterns, '.'),
32	      );
33	    }
34	  }
35	
36	  private loadPatternsForFile(patternsFilePath: string): Ignore {
37	    let content: string;
38	    try {
39	      content = fs.readFileSync(patternsFilePath, 'utf-8');
40	    } catch {
41	      return ignore();
42	    }
43	
44	    const isExcludeFile = patternsFilePath.endsWith(
45	      path.join('.git', 'info', 'exclude'),
46	    );
47	
48	    const relativeBaseDir = isExcludeFile
49	      ? '.'
50	      : path
51	          .dirname(path.relative(this.projectRoot, patternsFilePath))
52	          .split(path.sep)
53	          .join(path.posix.sep);
54	
55	    const rawPatterns = content.split(/\r\n|\n|\r/);
56	    return ignore().add(this.processPatterns(rawPatterns, relativeBaseDir));
57	  }
58	
59	  private processPatterns(
60	    rawPatterns: string[],
61	    relativeBaseDir: string,
62	  ): string[] {
63	    return rawPatterns
64	      .map((p) => p.trimStart())
65	      .filter((p) => p !== '' && !p.startsWith('#'))
66	      .map((p) => {
67	        const isNegative = p.startsWith('!');
68	        if (isNegative) {
69	          p = p.substring(1);
70	        }
71	
72	        const isAnchoredInFile = p.startsWith('/');
73	        if (isAnchoredInFile) {
74	          p = p.substring(1);
75	        }
76	
77	        // An empty pattern can result from a negated pattern like `!`,
78	        // which we can ignore.
79	        if (p === '') {
80	          return '';
81	        }
82	
83	        let newPattern = p;
84	        if (relativeBaseDir && relativeBaseDir !== '.') {
85	          // Only in nested .gitignore files, the patterns need to be modified according to:
86	          // - If `a/b/.gitignore` defines `/c` then it needs to be changed to `/a/b/c`
87	          // - If `a/b/.gitignore` defines `c` then it needs to be changed to `/a/b/**/c`
88	          // - If `a/b/.gitignore` defines `c/d` then it needs to be changed to `/a/b/c/d`
89	
90	          if (!isAnchoredInFile && !p.includes('/')) {
91	            // If no slash and not anchored in file, it matches files in any
92	            // subdirectory.
93	            newPattern = path.posix.join('**', p);
94	          }
95	
96	          // Prepend the .gitignore file's directory.
97	          newPattern = path.posix.join(relativeBaseDir, newPattern);
98	
99	          // Anchor the pattern to a nested gitignore directory.
100	          if (!newPattern.startsWith('/')) {
101	            newPattern = '/' + newPattern;
102	          }
103	        }
104	
105	        // Anchor the pattern if originally anchored
106	        if (isAnchoredInFile && !newPattern.startsWith('/')) {
107	          newPattern = '/' + newPattern;
108	        }
109	
110	        if (isNegative) {
111	          newPattern = '!' + newPattern;
112	        }
113	
114	        return newPattern;
115	      })
116	      .filter((p) => p !== '');
117	  }
