119	  isIgnored(filePath: string, isDirectory: boolean): boolean {
120	    const normalizedPath = getNormalizedRelativePath(
121	      this.projectRoot,
122	      filePath,
123	      isDirectory,
124	    );
125	    // Root directory is never ignored by gitignore
126	    if (
127	      normalizedPath === null ||
128	      normalizedPath === '' ||
129	      normalizedPath === '/'
130	    ) {
131	      return false;
132	    }
133	
134	    try {
135	      const ig = ignore().add('.git'); // Always ignore .git
136	
137	      // Load global patterns from .git/info/exclude
138	      if (this.globalPatterns === undefined) {
139	        const excludeFile = path.join(
140	          this.projectRoot,
141	          '.git',
142	          'info',
143	          'exclude',
144	        );
145	        this.globalPatterns = fs.existsSync(excludeFile)
146	          ? this.loadPatternsForFile(excludeFile)
147	          : ignore();
148	      }
149	      ig.add(this.globalPatterns);
150	
151	      // Git checks directories hierarchically. If a parent directory is ignored,
152	      // its children are ignored automatically, and we can stop processing.
153	      const pathParts = normalizedPath.split('/');
154	      let currentAbsDir = this.projectRoot;
155	      const dirsToVisit = [this.projectRoot];
156	
157	      for (let i = 0; i < pathParts.length - 1; i++) {
158	        currentAbsDir = path.join(currentAbsDir, pathParts[i]);
159	        dirsToVisit.push(currentAbsDir);
160	      }
161	
162	      for (const dir of dirsToVisit) {
163	        const relativeDir = path.relative(this.projectRoot, dir);
164	        if (relativeDir) {
165	          // Check if this parent directory is already ignored by patterns found so far
166	          const parentDirRelative = getNormalizedRelativePath(
167	            this.projectRoot,
168	            dir,
169	            true,
170	          );
171	          const currentIg = ignore().add(ig).add(this.processedExtraPatterns);
172	          if (parentDirRelative && currentIg.ignores(parentDirRelative)) {
173	            // Optimization: Stop once an ancestor is ignored
174	            break;
175	          }
176	        }
177	
178	        // Load and add patterns from .gitignore in the current directory
179	        let patterns = this.cache.get(dir);
180	        if (patterns === undefined) {
181	          const gitignorePath = path.join(dir, '.gitignore');
182	          patterns = fs.existsSync(gitignorePath)
183	            ? this.loadPatternsForFile(gitignorePath)
184	            : ignore();
185	          this.cache.set(dir, patterns);
186	        }
187	        ig.add(patterns);
188	      }
189	
190	      // Extra patterns (like .geminiignore) have final precedence
191	      return ig.add(this.processedExtraPatterns).ignores(normalizedPath);
192	    } catch {
193	      return false;
194	    }
195	  }
